CREATE TYPE "CommercialLegalIssuerVersionStatus" AS ENUM ('DRAFT', 'VERIFIED', 'ARCHIVED');
CREATE TYPE "CommercialLegalFieldApplicability" AS ENUM ('UNSPECIFIED', 'APPLICABLE', 'NOT_APPLICABLE');
CREATE TABLE "CommercialLegalIssuer" ("id" TEXT NOT NULL, "code" VARCHAR(100) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CommercialLegalIssuer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CommercialLegalIssuerVersion" ("id" TEXT NOT NULL, "commercialLegalIssuerId" TEXT NOT NULL, "versionNumber" INTEGER NOT NULL, "status" "CommercialLegalIssuerVersionStatus" NOT NULL DEFAULT 'DRAFT', "legalName" TEXT NOT NULL, "tradeName" TEXT, "legalForm" TEXT, "country" CHAR(2), "subdivision" TEXT, "addressLine1" TEXT, "addressLine2" TEXT, "city" TEXT, "postalCode" TEXT, "officialEmail" TEXT, "officialPhone" TEXT, "website" TEXT, "businessNumber" TEXT, "businessNumberApplicability" "CommercialLegalFieldApplicability" NOT NULL DEFAULT 'UNSPECIFIED', "federalTaxNumber" TEXT, "federalTaxApplicability" "CommercialLegalFieldApplicability" NOT NULL DEFAULT 'UNSPECIFIED', "provincialTaxNumber" TEXT, "provincialTaxApplicability" "CommercialLegalFieldApplicability" NOT NULL DEFAULT 'UNSPECIFIED', "referenceCurrency" CHAR(3), "representativeName" TEXT, "representativeTitle" TEXT, "representativeEmail" TEXT, "authorizedSignatoryName" TEXT, "authorizedSignatoryTitle" TEXT, "authorizedSignatoryEmail" TEXT, "provenance" VARCHAR(100) NOT NULL, "contentHash" CHAR(64) NOT NULL, "lifecycleReason" TEXT, "lockVersion" INTEGER NOT NULL DEFAULT 0, "createdByUserId" TEXT, "verifiedByUserId" TEXT, "archivedByUserId" TEXT, "verifiedAt" TIMESTAMP(3), "archivedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CommercialLegalIssuerVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CommercialLegalIssuerSnapshot" ("id" TEXT NOT NULL, "proposalRevisionId" TEXT NOT NULL, "legalIssuerVersionId" TEXT NOT NULL, "issuerCode" VARCHAR(100) NOT NULL, "issuerVersionNumber" INTEGER NOT NULL, "legalName" TEXT NOT NULL, "tradeName" TEXT, "legalForm" TEXT, "country" CHAR(2), "subdivision" TEXT, "addressLine1" TEXT, "addressLine2" TEXT, "city" TEXT, "postalCode" TEXT, "officialEmail" TEXT, "officialPhone" TEXT, "website" TEXT, "businessNumber" TEXT, "businessNumberApplicability" "CommercialLegalFieldApplicability" NOT NULL, "federalTaxNumber" TEXT, "federalTaxApplicability" "CommercialLegalFieldApplicability" NOT NULL, "provincialTaxNumber" TEXT, "provincialTaxApplicability" "CommercialLegalFieldApplicability" NOT NULL, "referenceCurrency" CHAR(3), "representativeName" TEXT, "representativeTitle" TEXT, "representativeEmail" TEXT, "authorizedSignatoryName" TEXT, "authorizedSignatoryTitle" TEXT, "authorizedSignatoryEmail" TEXT, "capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "snapshotHash" CHAR(64) NOT NULL, "capturedByUserId" TEXT, CONSTRAINT "CommercialLegalIssuerSnapshot_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommercialLegalIssuer_code_key" ON "CommercialLegalIssuer"("code");
CREATE UNIQUE INDEX "CommercialLegalIssuerVersion_commercialLegalIssuerId_versio_key" ON "CommercialLegalIssuerVersion"("commercialLegalIssuerId", "versionNumber");
CREATE INDEX "CommercialLegalIssuerVersion_commercialLegalIssuerId_status_idx" ON "CommercialLegalIssuerVersion"("commercialLegalIssuerId", "status");
CREATE UNIQUE INDEX "CommercialLegalIssuerVersion_one_draft_key" ON "CommercialLegalIssuerVersion"("commercialLegalIssuerId") WHERE "status"='DRAFT';
CREATE UNIQUE INDEX "CommercialLegalIssuerSnapshot_proposalRevisionId_key" ON "CommercialLegalIssuerSnapshot"("proposalRevisionId");
CREATE INDEX "CommercialLegalIssuerSnapshot_legalIssuerVersionId_captured_idx" ON "CommercialLegalIssuerSnapshot"("legalIssuerVersionId", "capturedAt");
ALTER TABLE "CommercialLegalIssuerVersion" ADD CONSTRAINT "CommercialLegalIssuerVersion_commercialLegalIssuerId_fkey" FOREIGN KEY ("commercialLegalIssuerId") REFERENCES "CommercialLegalIssuer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CommercialLegalIssuerVersion" ADD CONSTRAINT "CommercialLegalIssuerVersion_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CommercialLegalIssuerVersion" ADD CONSTRAINT "CommercialLegalIssuerVersion_verifiedByUserId_fkey" FOREIGN KEY ("verifiedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CommercialLegalIssuerVersion" ADD CONSTRAINT "CommercialLegalIssuerVersion_archivedByUserId_fkey" FOREIGN KEY ("archivedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CommercialLegalIssuerSnapshot" ADD CONSTRAINT "CommercialLegalIssuerSnapshot_proposalRevisionId_fkey" FOREIGN KEY ("proposalRevisionId") REFERENCES "CommercialProposalRevision"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CommercialLegalIssuerSnapshot" ADD CONSTRAINT "CommercialLegalIssuerSnapshot_legalIssuerVersionId_fkey" FOREIGN KEY ("legalIssuerVersionId") REFERENCES "CommercialLegalIssuerVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CommercialLegalIssuerSnapshot" ADD CONSTRAINT "CommercialLegalIssuerSnapshot_capturedByUserId_fkey" FOREIGN KEY ("capturedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CommercialLegalIssuerVersion" ADD CONSTRAINT "CommercialLegalIssuerVersion_lifecycle_check" CHECK (("status"='DRAFT' AND "verifiedAt" IS NULL AND "archivedAt" IS NULL) OR ("status"='VERIFIED' AND "verifiedAt" IS NOT NULL AND "verifiedByUserId" IS NOT NULL AND "archivedAt" IS NULL) OR ("status"='ARCHIVED' AND "verifiedAt" IS NOT NULL AND "verifiedByUserId" IS NOT NULL AND "archivedAt" IS NOT NULL AND "archivedByUserId" IS NOT NULL));
ALTER TABLE "CommercialLegalIssuerVersion" ADD CONSTRAINT "CommercialLegalIssuerVersion_values_check" CHECK ("versionNumber">0 AND "lockVersion">=0 AND LENGTH(BTRIM("legalName"))>0 AND LENGTH(BTRIM("provenance"))>0);
ALTER TABLE "CommercialLegalIssuerVersion" ADD CONSTRAINT "CommercialLegalIssuerVersion_applicability_check" CHECK (("businessNumberApplicability"<>'APPLICABLE' OR "businessNumber" IS NOT NULL) AND ("businessNumberApplicability"<>'NOT_APPLICABLE' OR "businessNumber" IS NULL) AND ("federalTaxApplicability"<>'APPLICABLE' OR "federalTaxNumber" IS NOT NULL) AND ("federalTaxApplicability"<>'NOT_APPLICABLE' OR "federalTaxNumber" IS NULL) AND ("provincialTaxApplicability"<>'APPLICABLE' OR "provincialTaxNumber" IS NOT NULL) AND ("provincialTaxApplicability"<>'NOT_APPLICABLE' OR "provincialTaxNumber" IS NULL));
CREATE FUNCTION protect_commercial_legal_issuer_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Legal issuer versions are retained'; END IF; IF OLD."status" IN ('VERIFIED','ARCHIVED') THEN IF OLD."status"='VERIFIED' AND NEW."status"='ARCHIVED' AND ROW(NEW."commercialLegalIssuerId",NEW."versionNumber",NEW."legalName",NEW."tradeName",NEW."legalForm",NEW."country",NEW."subdivision",NEW."addressLine1",NEW."addressLine2",NEW."city",NEW."postalCode",NEW."officialEmail",NEW."officialPhone",NEW."website",NEW."businessNumber",NEW."businessNumberApplicability",NEW."federalTaxNumber",NEW."federalTaxApplicability",NEW."provincialTaxNumber",NEW."provincialTaxApplicability",NEW."referenceCurrency",NEW."representativeName",NEW."representativeTitle",NEW."representativeEmail",NEW."authorizedSignatoryName",NEW."authorizedSignatoryTitle",NEW."authorizedSignatoryEmail",NEW."provenance",NEW."contentHash",NEW."createdByUserId",NEW."verifiedByUserId",NEW."verifiedAt",NEW."createdAt") IS NOT DISTINCT FROM ROW(OLD."commercialLegalIssuerId",OLD."versionNumber",OLD."legalName",OLD."tradeName",OLD."legalForm",OLD."country",OLD."subdivision",OLD."addressLine1",OLD."addressLine2",OLD."city",OLD."postalCode",OLD."officialEmail",OLD."officialPhone",OLD."website",OLD."businessNumber",OLD."businessNumberApplicability",OLD."federalTaxNumber",OLD."federalTaxApplicability",OLD."provincialTaxNumber",OLD."provincialTaxApplicability",OLD."referenceCurrency",OLD."representativeName",OLD."representativeTitle",OLD."representativeEmail",OLD."authorizedSignatoryName",OLD."authorizedSignatoryTitle",OLD."authorizedSignatoryEmail",OLD."provenance",OLD."contentHash",OLD."createdByUserId",OLD."verifiedByUserId",OLD."verifiedAt",OLD."createdAt") THEN RETURN NEW; END IF; RAISE EXCEPTION 'Verified legal issuer version is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER commercial_legal_issuer_version_protect BEFORE UPDATE OR DELETE ON "CommercialLegalIssuerVersion" FOR EACH ROW EXECUTE FUNCTION protect_commercial_legal_issuer_version();
CREATE FUNCTION protect_commercial_legal_issuer_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Legal issuer snapshots are immutable'; END $$;
CREATE TRIGGER commercial_legal_issuer_snapshot_protect BEFORE UPDATE OR DELETE ON "CommercialLegalIssuerSnapshot" FOR EACH ROW EXECUTE FUNCTION protect_commercial_legal_issuer_snapshot();
